import {ensureScene} from './layout-model.mjs';
import {roomView,propsView,installRoom} from './room.js';
import {wiringGraph,installGraph,drawGraph} from './wiring-graph.mjs';
import {defaultLibrary,ensureInstallation,migrateInfrastructure,addInfrastructure,makeBox,addFieldDevice,componentPlacement,routeSpecs,routeGeometry} from './installation-model.mjs';
import {boxesView,standardsView,bomView,helpView,installInstallation,drawBoxConnections,openBox} from './installation-ui.mjs';
import {APP_VERSION} from './version.mjs';
import {createDemoProject} from './demo-project.mjs';
import {tailoredInitial,calculate,validateProject,recommendSections,BOARDS,AWG,PSU_MODELS,newSegment,uid} from './model.mjs';
const testing=new URLSearchParams(location.search).has('test');
let project=tailoredInitial(),view='room',page='workspace',selected='r1',si=0,storageOK=true;
let library,demo=false,previousProject=null,previousLibrary=null,targetBoxId='';
try{library=JSON.parse(localStorage.getItem('pixel-workbench-library-v1'))||defaultLibrary();}catch{library=defaultLibrary();}
try{localStorage.setItem('pixel-workbench-library-v1',JSON.stringify(library));}catch{}
project.controllers.forEach(c=>c.io=['','','']);
try{const raw=localStorage.getItem('pixel-workbench-v1');if(raw&&!testing)project=validateProject(JSON.parse(raw));}catch{storageOK=false;}
validateProject(project);
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(n,d=1)=>Number(n).toFixed(d);
const btn=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const inp=(label,value,path,o={})=>`<label>${label}<input type="${o.text?'text':'number'}" value="${esc(value)}" data-bind="${path}" ${o.text?'maxlength="200"':`required min="${o.min??0}" max="${o.max??100000}" step="${o.step??'any'}"`}></label>`;
const sel=(label,value,path,items)=>`<label>${label}<select data-bind="${path}">${items.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
const awgs=Object.keys(AWG).map(a=>[a,a+' AWG']),psuOpts=()=>project.psus.map(p=>[p.id,p.name]),kindOpts=[['seed','Seed pixels'],['bullet','Bullet pixels'],['flood','Pixel floods']];
const active=()=>project.chains.find(c=>c.id===selected)||project.chains[0];
function save(){if(testing||demo)return;try{localStorage.setItem('pixel-workbench-v1',JSON.stringify(project));storageOK=true;}catch{storageOK=false;toast('Browser storage is full. Export your project now to preserve changes.');}}
function toast(m){$('#toast').textContent=m;$('#toast').classList.add('toast-show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('toast-show'),5000);}
function render(){const migrated=migrateInfrastructure(project,library);ensureScene(project);const r=calculate(project);if(!project.chains.some(c=>c.id===selected))selected=project.chains[0]?.id;if(active())si=Math.min(si,active().segments.length-1);const pages=[['workspace','⌁','Wiring workspace'],['hardware','▤','Hardware & power'],['presets','▧','Pixel presets'],['props','◉','Props'],['guide','☷','Wiring guide'],['boxes','▣','Controller boxes'],['standards','⌁','Standards'],['bom','☷','Bill of materials'],['help','ⓘ','Info / Help']];$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="page:workspace"><span class="brandmark">▦</span><span>pixel<span class="light">workbench</span></span></a><div class="workspace-label">YOUR WORKSPACE</div><div class="project-card"><span class="project-icon">P</span><div><strong>${esc(project.name)}</strong><small>${demo?'DEMO MODE':'12 V pixel system'}</small></div></div><nav aria-label="Main navigation">${pages.map(([id,ic,label])=>btn(`<span class="nav-icon">${ic}</span>${label}`,'page:'+id,'nav '+(id===page?'active':''),id===page?'aria-current="page"':'')).join('')}</nav><div class="sidebar-bottom"><span class="version">WORKBENCH / V${APP_VERSION}</span><p>From first pixel<br>to lights on.</p><div class="save-state">○ Device-local project</div>${btn('↓ Save project','export','subtle')}${btn('↑ Open project','import','subtle')}${demo?btn('Exit demo','exit-demo','subtle')+btn('Save demo as project','save-demo','subtle'):btn('Open demo','open-demo','subtle')}${btn('Blank project','blank-project','subtle danger')}</div></aside><main><header class="topbar"><div class="crumb">Projects <span>/</span> ${esc(project.name)}</div><div class="top-actions"><span class="local-label">${storageOK?'Saved on this device':'Save a JSON backup'}</span>${btn('↓ Save project','export','btn')}${btn('↑ Open','import','btn')}${btn('↗ Wiring guide','page:guide','btn')}${demo?btn('Exit demo','exit-demo','btn'):btn('Open demo','open-demo','btn')}${btn('Blank project','blank-project','btn danger')}</div></header><section class="page-head"><div><div class="eyebrow">PLAN • WIRE • DEPLOY</div><h1>${pages.find(x=>x[0]===page)[2]}</h1><p>${({workspace:'Every connection, with the power to back it up.',hardware:'Give every circuit a source.',presets:'Your repeatable building blocks.',props:'Pixel shapes, built for your space.',guide:'A build sheet for the workbench and the field.',boxes:'Arrange and connect the parts inside each installation box.',standards:'Reusable cables and hardware for every project.',bom:'A practical packing and ordering list.',help:'How to use this toolkit and what changed.'})[page]}</p></div>${page==='hardware'?btn('+ Add controller','add-controller','btn primary'):btn('+ Controller box','new-box-main','btn primary')}</section><div class="summary"><div><span>ADDRESSABLE DEVICES</span><strong>${r.pixels.toLocaleString()} <small>across ${project.chains.length} ports</small></strong></div><div><span>ESTIMATED LOAD</span><strong>${fmt(r.watts)} <small>W at ${project.brightness}%</small></strong></div><div><span>PSU DESIGN BUDGET</span><strong>${fmt(project.psus.reduce((n,p)=>n+p.watts,0)*project.headroom/100,0)} <small>W total</small></strong></div><div><span>PLAN CHECKS</span><strong class="amber">${r.warnings.filter(w=>w.level!=='info').length} <small>+ ${r.warnings.filter(w=>w.level==='info').length} assumptions</small></strong></div></div><section id="content">${({workspace:()=>workspace(r),hardware:()=>hardware(r),presets:()=>presets(),props:()=>propsView(project),guide:()=>guide(r),boxes:()=>boxesView(project,library),standards:()=>standardsView(library),bom:()=>bomView(project),help:()=>helpView()})[page]()}</section><footer><span><i class="status-dot"></i> Changes sync across views</span><span>DC planning estimates • Verify against your actual hardware</span></footer></main><dialog id="modal"></dialog>`;if(view==='visual'&&page==='workspace')requestAnimationFrame(drawGraph);if(page==='boxes')requestAnimationFrame(drawBoxConnections);if(migrated)save();}
function checks(r){return `<div class="checks panel"><div class="checks-title"><h3>Plan checks <span>${r.warnings.length}</span></h3><small>Includes 100% white checks</small></div>${r.warnings.map(w=>`<div class="check"><span class="check-icon ${w.level}">${w.level==='info'?'i':'!'}</span><div><strong>${esc(w.title)}</strong><p>${esc(w.detail)}</p></div>${w.chain?btn('View','select:'+w.chain,'text-btn'):''}</div>`).join('')||'<p class="empty">No calculated limits exceeded. Verify the assumptions before building.</p>'}</div>`;}
function powerCards(r){return `<div class="power-strip">${project.psus.map(ps=>{const load=r.psus[ps.id],pct=load.watts/ps.watts*100;return `<button class="panel psu-mini" style="border-top:3px solid ${project.scene.placements['psu:'+ps.id]?.color||'#39886e'}" data-action="page:hardware"><div><span class="power-icon">ϟ</span><strong>${esc(ps.name)}</strong><span>${fmt(load.watts)} / ${ps.watts} W</span></div><div class="meter ${pct>project.headroom?'over':''}"><i style="width:${Math.min(100,pct)}%"></i><b style="left:${project.headroom}%"></b></div><small>${fmt(load.amps,2)} A · ${fmt(load.fullWatts)} W at full white</small></button>`}).join('')}</div>`;}
function workspace(r){const selector=`<div class="segmented" role="group" aria-label="Editor view">${btn('⌘ Visual','view:visual',view==='visual'?'selected':'')}${btn('☷ Data entry','view:form',view==='form'?'selected':'')}${btn('▧ Room layout','view:room',view==='room'?'selected':'')}</div>`;if(view==='room')return `<div class="workspace-bar">${selector}${btn('+ Add output','add-chain','btn')}</div>${roomView(project)}`;return `<div class="workspace-bar"><div class="segmented" role="group" aria-label="Editor view">${btn('⌘ Visual','view:visual',view==='visual'?'selected':'',`aria-pressed="${view==='visual'}"`)}${btn('☷ Data entry','view:form',view==='form'?'selected':'',`aria-pressed="${view==='form'}"`)}${btn('▧ Room layout','view:room','')}</div><div class="brightness"><label for="brightness">Brightness</label><input id="brightness" aria-label="Planning brightness" type="range" min="1" max="100" value="${project.brightness}" data-bind="brightness"><strong>${project.brightness}%</strong></div>${btn('+ Add output','add-chain','btn')}</div>${view==='visual'?visual(r):''}<div class="editor-layout"><div>${view==='visual'?'':tableView(r)}${chainDetail(r)}${powerCards(r)}</div><aside class="inspector panel"><div class="inspector-title"><h3>Output inspector</h3><span class="pill">LIVE</span></div>${inspector(r)}</aside></div>${checks(r)}<details class="method panel"><summary>Calculation assumptions & supported wiring</summary>${method()}</details>`;}
function visual(r){return wiringGraph(project,r);}
function tableView(r){return `<div class="panel table-panel"><table><thead><tr><th>Port</th><th>Chain</th><th>Load</th><th>Channels</th></tr></thead><tbody>${project.chains.map(ch=>`<tr class="${ch.id===selected?'row-selected':''}"><td>${btn('P'+ch.port,'select:'+ch.id,'port-button')}</td><td>${btn(esc(ch.name),'select:'+ch.id,'text-btn')}<small>${esc(project.controllers.find(c=>c.id===ch.controller).name)} · ${ch.segments.length} segments</small></td><td>${fmt(r.chains[ch.id].watts)} W</td><td>${r.chains[ch.id].start}–${r.chains[ch.id].end}</td></tr>`).join('')}</tbody></table>${!project.chains.length?'<p class="empty">Add an output to begin.</p>':''}</div>`;}
function chainDetail(r){const ch=active();if(!ch)return '';const cr=r.chains[ch.id];return `<div class="chain-detail panel"><div class="checks-title"><h3>${esc(ch.name)}</h3><span class="metadata">CH ${cr.start}–${cr.end}</span></div><div class="segment-flow"><div class="flow-source"><span>P${ch.port}</span><small>Data out</small></div>${ch.segments.map((s,i)=>`<div class="flow-link"><span>${s.leadM} m<br>${s.leadAwg} AWG</span><b>→</b></div><button data-action="segment:${i}" class="segment-block ${i===si?'selected':''}" style="border-top:3px solid ${project.scene.placements['segment:'+s.id]?.color||'#39886e'}">${s.inject?`<span class="injection-label">↓ ${esc(project.distros.find(d=>d.id===s.distro)?.name)} · V+ break</span>`:''}<span class="segment-type">${s.kind==='flood'?'▣':'● ● ●'}</span><strong>${s.count} ${s.kind}${s.count>1?'s':''}</strong><small>${fmt(s.count*s.watts*project.brightness/100)} W · ${fmt(Math.max(0,cr.segments.find(x=>x.id===s.id)?.endV||0),2)} V</small></button>`).join('')}</div><div class="flow-actions">${btn('+ Add pixels / flood','add-segment','btn')}${btn('Suggest injection','auto-inject','btn')}${btn('Split manually','split','text-btn')}${btn('Save as preset','save-preset','text-btn')}</div></div>`;}
function inspector(r){const ch=active();if(!ch)return '<p class="empty">Select or add an output.</p>';const ci=project.chains.indexOf(ch),c=project.controllers.find(c=>c.id===ch.controller),s=ch.segments[si],path=`chains.${ci}`,sp=`${path}.segments.${si}`,sr=r.chains[ch.id].segments.find(x=>x.id===s.id);return `<div class="inspector-body">${inp('Output name',ch.name,`${path}.name`,{text:true})}<div class="two">${sel('Controller',ch.controller,`${path}.controller`,project.controllers.map(c=>[c.id,c.name]))}${sel('Data port',ch.port,`${path}.port`,Array.from({length:BOARDS[c.model].ports},(_,i)=>[i+1,'Port '+(i+1)]))}</div><div class="segment-select"><span>SEGMENT ${si+1} / ${ch.segments.length}</span><div>${ch.segments.map((s,i)=>btn(String(i+1),'segment:'+i,i===si?'selected':'',`aria-label="Edit segment ${i+1}"`)).join('')}</div></div>${sel('Load type',s.kind,`${sp}.kind`,kindOpts)}<div class="two">${inp('Quantity',s.count,`${sp}.count`,{min:1,step:1})}${s.kind==='flood'?sel('Input W / flood',s.watts,`${sp}.watts`,[10,20,30].map(w=>[w,w+' W'])):inp('Full-white W / pixel',s.watts,`${sp}.watts`,{min:.001,max:1000})}</div><div class="two">${sel('Channels / device',s.channels,`${sp}.channels`,[[3,'3 · RGB'],[4,'4 · RGBW']])}${inp('Pixel pitch (m)',s.spacing,`${sp}.spacing`,{max:100})}</div>${sel('Wire between devices',s.stringAwg,`${sp}.stringAwg`,awgs)}<div class="section-label">${si===0?'CONTROLLER':'PREVIOUS SEGMENT'} → DATA IN</div><div class="two">${inp('Cable length (m)',s.leadM,`${sp}.leadM`,{max:10000})}${sel('Cable gauge',s.leadAwg,`${sp}.leadAwg`,awgs)}</div><div class="section-label">POWER SOURCE</div>${sel('Feed this segment',s.inject?'external':'upstream',`${sp}.powerMode`,[['upstream',si===0?'From Baldrick bank':'From previous segment'],['external','Distro feed · V+ isolated']])}${s.inject?`${sel('Fused distro',s.distro,`${sp}.distro`,project.distros.map(d=>[d.id,d.name+' / '+project.psus.find(p=>p.id===d.psu)?.name]))}${sel('Distro output',s.distroPort,`${sp}.distroPort`,Array.from({length:project.distros.find(d=>d.id===s.distro)?.outputs||0},(_,i)=>[i+1,'Output '+(i+1)]))}${sel('Distro output',s.distroPort,`${sp}.distroPort`,Array.from({length:project.distros.find(d=>d.id===s.distro)?.outputs||0},(_,i)=>[i+1,'Output '+(i+1)]))}<div class="two">${inp('Feed length (m)',s.feedM,`${sp}.feedM`,{max:10000})}${sel('Feed gauge',s.feedAwg,`${sp}.feedAwg`,awgs)}</div>${inp('Branch fuse (A)',s.fuse,`${sp}.fuse`,{min:.1,max:100})}<p class="wire-note">Disconnect upstream V+ here. Data and the required signal reference continue. Run a dedicated load return to this PSU.</p>`:`<p class="source-note">${esc(project.psus.find(p=>p.id===sr?.source)?.name)} · ${si===0?'bank '+(r.chains[ch.id].bank+1):'upstream section'}</p>`}<div class="voltage-result"><span>Estimated end voltage · this segment</span><strong>${sr?.endV>0?fmt(sr.endV,2):'—'} <small>V</small></strong><small>${fmt(sr?.dropPct||0)}% drop · ${fmt(sr?.amps||0,2)} A device load</small></div><p class="micro">Linear brightness estimate. Confirm actual full-white watts, pixel pitch and wire size.</p><div class="inspector-actions">${btn('Move earlier','move:-1','text-btn')}${btn('Move later','move:1','text-btn')}${btn('Remove segment','remove-segment','text-btn danger')}${btn('Remove output','remove-chain','text-btn danger')}</div></div>`;}
function hardware(r){return `<section class="panel settings"><div class="field-grid"><label>Add new hardware inside<select data-hardware-box><option value="">${project.installation.boxes.length?'Choose a controller box':'Create a box automatically'}</option>${project.installation.boxes.map(b=>`<option value="${esc(b.id)}" ${b.id===targetBoxId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>${btn('+ New box','new-box-main','btn')}</div><h2>Project settings</h2><div class="field-grid">${inp('Project name',project.name,'name',{text:true})}${inp('PSU design budget (%)',project.headroom,'headroom',{min:1,max:100})}${inp('Voltage-drop warning (%)',project.dropLimit,'dropLimit',{min:1,max:50})}${inp('First absolute channel',project.startChannel,'startChannel',{min:1,max:1e8,step:1})}</div><p class="micro">The design budget is your preference. Nameplate capacity is checked separately. This version models 12 V systems.</p></section><div class="catalog-tools"><input type="search" data-catalog-search="hardware" placeholder="Search project hardware" aria-label="Search hardware"><select data-catalog-category="hardware" aria-label="Filter hardware category"><option value="">All categories</option><option>Controller</option><option>Power</option><option>Input board</option><option>Relay board</option></select></div><div class="section-heading"><h2>Power supplies <span>${project.psus.length}</span></h2>${btn('+ Add PSU','add-psu','btn')}</div><div class="hardware-grid">${project.psus.map((ps,i)=>`<section class="panel hardware-card" data-catalog-item="hardware" data-category="Power" data-search="${esc(ps.name.toLowerCase())}"><div class="card-heading"><h3>ϟ ${esc(ps.name)}</h3>${btn('Remove','remove-psu:'+ps.id,'text-btn danger')}</div>${inp('Label',ps.name,`psus.${i}.name`,{text:true})}${sel('PSU model',ps.model,`psus.${i}.model`,Object.entries(PSU_MODELS).map(([id,m])=>[id,m.name]))}<div class="two">${inp('Rated output (W)',ps.watts,`psus.${i}.watts`,{min:1})}<div class="readout"><span>Nominal output</span><strong>12 V / ${fmt(ps.watts/12,2)} A</strong></div></div><div class="meter ${r.psus[ps.id].watts>ps.watts*project.headroom/100?'over':''}"><i style="width:${Math.min(100,r.psus[ps.id].watts/ps.watts*100)}%"></i><b style="left:${project.headroom}%"></b></div><p class="micro">${fmt(r.psus[ps.id].watts)} W planned · ${fmt(r.psus[ps.id].fullWatts)} W full white</p></section>`).join('')}</div><div class="section-heading"><h2>Fused distribution</h2>${btn('+ Add distro','add-distro','btn')}</div><div class="hardware-grid">${project.distros.map((d,i)=>`<section class="panel hardware-card" data-catalog-item="hardware" data-category="Power" data-search="${esc(d.name.toLowerCase())}"><div class="card-heading"><h3>${esc(d.name)}</h3>${btn('Remove','remove-distro:'+d.id,'text-btn danger')}</div>${inp('Label',d.name,`distros.${i}.name`,{text:true})}${sel('Power supply',d.psu,`distros.${i}.psu`,psuOpts())}${sel('PSU DC terminal',d.psuPort,`distros.${i}.psuPort`,[[1,'DC 1'],[2,'DC 2'],[3,'DC 3']])}<div class="two">${inp('Output count',d.outputs,`distros.${i}.outputs`,{min:1,max:100,step:1})}${inp('Total rating (A)',d.amps,`distros.${i}.amps`,{min:.1,max:1000})}</div>${inp('Per-output fuse ceiling (A)',d.fuse,`distros.${i}.fuse`,{min:.1,max:100})}<div class="distro-ports">${Array.from({length:Math.min(24,d.outputs)},(_,j)=>`<span class="${j<r.distros[d.id].feeds?'used':''}">${j+1}</span>`).join('')}</div><p class="micro">${r.distros[d.id].feeds} / ${d.outputs} outputs · ${fmt(r.distros[d.id].amps,2)} A / ${d.amps} A. Limits are user assumptions; confirm against the board.</p></section>`).join('')}</div><div class="section-heading"><h2>Controllers & banks</h2></div>${project.controllers.map((c,i)=>`<section class="panel hardware-card" data-catalog-item="hardware" data-category="Controller" data-search="${esc(c.name.toLowerCase())}"><div class="card-heading"><h3>${BOARDS[c.model].name} · ${BOARDS[c.model].ports} outputs</h3><a href="${BOARDS[c.model].url}" target="_blank" rel="noreferrer">Board manual ↗</a></div><div class="field-grid">${inp('Controller name',c.name,`controllers.${i}.name`,{text:true})}${inp('IP / hostname',c.host,`controllers.${i}.host`,{text:true})}</div><div class="bank-grid">${c.bankPsus.map((id,b)=>`<div class="bank-card"><h3>Bank ${b+1} <small>ports ${b*4+1}–${Math.min(b*4+4,BOARDS[c.model].ports)}</small></h3>${sel('Supply',id,`controllers.${i}.bankPsus.${b}`,psuOpts())}${sel('PSU DC terminal',c.bankPsuPorts[b],`controllers.${i}.bankPsuPorts.${b}`,[[1,'DC 1'],[2,'DC 2'],[3,'DC 3']])}${inp('Bank limit (A; 0 = unknown)',c.bankLimits[b],`controllers.${i}.bankLimits.${b}`,{max:1000})}<div class="two">${inp('PSU lead (m)',c.bankM[b],`controllers.${i}.bankM.${b}`,{max:10000})}${sel('PSU lead gauge',c.bankAwg[b],`controllers.${i}.bankAwg.${b}`,awgs)}</div><p class="micro">${fmt(r.banks[c.id+':'+b].amps,2)} A planned / ${fmt(r.banks[c.id+':'+b].fullAmps,2)} A full white</p></div>`).join('')}</div><h3 class="io-heading">Input buttons / triggers</h3><div class="field-grid">${c.io.map((label,j)=>inp('Input '+(j+1)+' · button / action',label,`controllers.${i}.io.${j}`,{text:true})).join('')}</div><p class="micro">Action labels only; configure triggers on the hardware. Supplied port fuses: ${BOARDS[c.model].fuse} A. Aggregate bank ratings are unverified.</p>${btn('Remove controller','remove-controller:'+c.id,'text-btn danger')}</section>`).join('')}<div class="section-heading"><h2>Relays & additional inputs</h2>${btn('+ Add board','add-aux','btn')}</div><div class="hardware-grid">${project.aux.map((a,i)=>`<section class="panel hardware-card" data-catalog-item="hardware" data-category="Input board" data-search="${esc(a.name.toLowerCase())}"><div class="card-heading"><h3>${a.model==='switchy'?'BaldrickSwitchy · 4 relays':'BaldrickInput1 · 1 input'}</h3>${btn('Remove','remove-aux:'+a.id,'text-btn danger')}</div>${inp('Board name',a.name,`aux.${i}.name`,{text:true})}${sel('Board PSU',a.psu,`aux.${i}.psu`,psuOpts())}${inp('Board allowance (W)',a.watts,`aux.${i}.watts`,{max:1000})}${a.labels.map((l,j)=>inp(`${a.model==='switchy'?'Relay':'Input'} ${j+1} · device / action`,l,`aux.${i}.labels.${j}`,{text:true})).join('')}<p class="micro">Switched loads and button lamps need a separate load design. This allowance includes only board consumption.</p></section>`).join('')||'<p class="empty">Add a Switchy or Input1 board to label its connections.</p>'}</div>${checks(r)}`;}
function presets(){return `<div class="notice">Seed and bullet values are starting assumptions. Use measured full-white electrical input power for your pixels. Flood presets are 10, 20 and 30 W per fixture.</div><div class="section-heading"><h2>Your pixel library</h2>${btn('+ New preset','new-preset','btn primary')}</div><div class="hardware-grid">${project.presets.map((p,i)=>`<section class="panel hardware-card"><div class="card-heading"><span class="preset-icon">${p.kind==='flood'?'▣':'● ● ●'}</span>${btn('Remove','remove-preset:'+p.id,'text-btn danger')}</div>${inp('Preset name',p.name,`presets.${i}.name`,{text:true})}${sel('Type',p.kind,`presets.${i}.kind`,kindOpts)}<div class="two">${inp('Quantity',p.count,`presets.${i}.count`,{min:1,step:1})}${inp('Full-white W / device',p.watts,`presets.${i}.watts`,{min:.001,max:1000})}</div><div class="two">${inp('Pitch (m)',p.spacing,`presets.${i}.spacing`,{max:100})}${sel('String wire',p.stringAwg,`presets.${i}.stringAwg`,awgs)}</div>${sel('Channels / device',p.channels,`presets.${i}.channels`,[[3,'3 · RGB'],[4,'4 · RGBW']])}<div class="preset-footer"><span>${fmt(p.count*p.watts)} W full white</span>${btn('Add to chain','use-preset:'+p.id,'btn')}</div></section>`).join('')}</div>`;}
function sourceFor(ch,s,r){const cr=r.chains[ch.id],sr=cr.segments.find(x=>x.id===s.id),ps=project.psus.find(p=>p.id===sr?.source);return s.inject?`${project.distros.find(d=>d.id===s.distro)?.name} / ${ps?.name}`:`${ps?.name} via ${ch.segments[0].id===s.id?'Baldrick bank '+(cr.bank+1):'upstream section'}`;}
function physicalCableGuide(){const rows=routeSpecs(project).map(spec=>({spec,g:routeGeometry(project,spec),record:project.installation?.routes?.[spec.id]})).filter(x=>x.g);return `<h3>06 / Physical cable schedule</h3><p>Lengths follow the 2D room routes. Service allowance is included only when enabled; it is separate from electrical wire-drop inputs.</p><div class="table-panel"><table><thead><tr><th>Route</th><th>Type</th><th>Routed</th><th>Required</th><th>Assigned cable</th><th>Fit</th></tr></thead><tbody>${rows.map(({spec,g,record})=>`<tr><td>${esc(spec.name)}</td><td>${esc(spec.kind)}</td><td>${fmt(g.routeM,2)} m</td><td>${fmt(g.requiredM,2)} m</td><td>${esc(record?.cableSnapshot?.name||'—')}${g.physicalM!=null?' · '+fmt(g.physicalM,2)+' m':''}</td><td>${g.shortByM>0?'SHORT '+fmt(g.shortByM,2)+' m':g.spareM!=null?fmt(g.spareM,2)+' m spare':'Unassigned'}</td></tr>`).join('')}</tbody></table></div>`;}
function guide(r){const feeds={};return `<div class="guide-actions">${btn('Print / save PDF','print','btn primary')}${btn('↓ Channel / port CSV','csv','btn')}${btn('↓ Project JSON','export','btn')}</div><article class="guide panel"><div class="guide-title"><div class="eyebrow">PIXEL WORKBENCH · BUILD SHEET</div><h2>${esc(project.name)}</h2><p>12 V DC · ${project.brightness}% planning brightness · ${r.channels} channels<br>${fmt(r.watts)} W estimated / ${fmt(r.fullWatts)} W full white</p></div><div class="notice">Planning draft · ${r.warnings.length} checks / assumptions. Confirm actual pixel power, cables, PSU model and bank limits before wiring. This guide does not configure FPP.</div><h3>01 / Power inventory</h3><div class="table-panel"><table><thead><tr><th>Supply</th><th>Model / rating</th><th>Planned / full white</th></tr></thead><tbody>${project.psus.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(PSU_MODELS[p.model].name)}<br>12 V · ${p.watts} W</td><td>${fmt(r.psus[p.id].watts)} / ${fmt(r.psus[p.id].fullWatts)} W</td></tr>`).join('')}</tbody></table></div><h3>02 / Controller bank feeds</h3>${project.controllers.map(c=>`<p><strong>${esc(c.name)} · ${BOARDS[c.model].name} · ${esc(c.host||'IP unassigned')}</strong><br>${c.bankPsus.map((id,b)=>`Bank ${b+1}, ports ${b*4+1}–${Math.min(b*4+4,BOARDS[c.model].ports)} ← ${esc(project.psus.find(p=>p.id===id)?.name)} DC ${c.bankPsuPorts[b]} · ${c.bankM[b]} m / ${c.bankAwg[b]} AWG · limit ${c.bankLimits[b]?c.bankLimits[b]+' A':'UNCONFIRMED'}`).join('<br>')}</p>`).join('')}<h3>03 / Distro feeds</h3>${project.distros.map(d=>`<p><strong>${esc(d.name)}</strong> ← ${esc(project.psus.find(p=>p.id===d.psu)?.name)} DC ${d.psuPort} · ${d.outputs} outputs · ${d.amps} A total · ${d.fuse} A/output ceiling.</p>`).join('')}<h3>04 / Data chains & power sections</h3>${project.chains.map(ch=>`<section class="guide-chain"><h4>P${ch.port} · ${esc(ch.name)} <span>CH ${r.chains[ch.id].start}–${r.chains[ch.id].end}</span></h4><p>Data from ${esc(project.controllers.find(c=>c.id===ch.controller).name)}. Keep devices in this order.</p><ol>${ch.segments.map((s,i)=>{const n=s.inject?s.distroPort:0;return `<li><strong>${s.count} ${s.kind}${s.count>1?'s':''} · ${s.watts} W each · ${s.channels} channels/device</strong><br>Data lead: ${s.leadM} m / ${s.leadAwg} AWG. String: ${s.spacing} m pitch / ${s.stringAwg} AWG.<br>Power: ${esc(sourceFor(ch,s,r))}${s.inject?` · distro output ${n} · ${s.feedM} m / ${s.feedAwg} AWG · ${s.fuse} A fuse.<br><strong class="amber">Disconnect upstream V+ at this segment.</strong> Continue data and the equipment-required signal reference. Run a dedicated load return to this PSU.`:` · ${i===0?BOARDS[project.controllers.find(c=>c.id===ch.controller).model].fuse+' A port fuse':'V+ and return continue from previous section'}.`}<br>Estimated endpoint: ${r.chains[ch.id].segments.find(x=>x.id===s.id)?.endV>0?fmt(r.chains[ch.id].segments.find(x=>x.id===s.id).endV,2)+' V':'outside model range'}.</li>`}).join('')}</ol></section>`).join('')}<h3>05 / Inputs & relays</h3>${project.controllers.map(c=>`<p>${esc(c.name)}: ${c.io.map((v,i)=>`Input ${i+1} — ${esc(v||'unassigned')}`).join('; ')}</p>`).join('')}${project.aux.map(a=>`<p><strong>${esc(a.name)}</strong> · ${a.model} · ${esc(project.psus.find(p=>p.id===a.psu)?.name)} / ${a.watts} W board allowance<br>${a.labels.map((v,i)=>`${i+1}: ${esc(v||'unassigned')}`).join('; ')}</p>`).join('')}${physicalCableGuide()}<h3>07 / FPP handoff</h3><p>The CSV is a planning schedule, not an FPP configuration file. Match these absolute channel ranges in your sequencer, FPP DDP output and Baldrick settings. Check protocol, colour order, RGB/RGBW compatibility, frame rate and brightness on the actual equipment.</p>${checks(r)}<h3>08 / Calculation notes & sources</h3>${method()}</article>`;}
function method(){return `<div class="method-copy"><p>Load = quantity × full-white input watts × brightness. This is a linear estimate; pixel idle current is not modelled. Full-white checks are separate. Controller self-consumption, connector losses and cable heating are excluded from PSU watt totals.</p><p>Wire drop = current × loop resistance. Enter one-way cable lengths; equal positive/return conductors and ideal copper at 20°C are assumed. Each wire section carries all downstream current. Pixel pitch and internal string wire are included. Temperature, cable material, connectors and device regulation affect real results. AWG alone does not establish safe ampacity.</p><p>Injection is modelled as isolated radial sections. Each distro feed starts a new power section with upstream V+ disconnected, even on a distro-only first segment. Its data lead carries no modelled power. Continuous V+ with multiple feeds is not solved in this version. Do not use the calculated balance for that topology or parallel independent PSU positives. Follow equipment requirements for data reference and load-return wiring.</p><p>Split & inject creates two separately fed sections. Recheck the result; this is a starting point, not a guaranteed injection interval. A zero or negative endpoint is outside the model’s useful range.</p><p>The Baldrick catalogue uses 2,250 channels/port at 40 fps and 7.5 A supplied port fuses. Aggregate bank limits remain unknown until entered. RGBW capability must be verified for the firmware and device type. PSU temperature/input derating must be checked against the manufacturer specification.</p><p>Sources: <a href="https://www.baldrickboard.com/en/boards/baldrick8/manual" target="_blank" rel="noreferrer">Baldrick8</a> · <a href="https://www.baldrickboard.com/en/boards/baldrick17/manual" target="_blank" rel="noreferrer">Baldrick17</a> · <a href="https://www.baldrickboard.com/en/boards/baldrickswitchy/manual" target="_blank" rel="noreferrer">Switchy</a> · <a href="https://www.baldrickboard.com/en/boards/baldrickinput1/manual" target="_blank" rel="noreferrer">Input1</a> · <a href="https://www.meanwell.com/Upload/PDF/RSP-320/RSP-320-SPEC.PDF" target="_blank" rel="noreferrer">Mean Well RSP-320</a> · <a href="https://www.meanwell.com/Upload/PDF/LRS-350/LRS-350-SPEC.PDF" target="_blank" rel="noreferrer">LRS-350</a> · <a href="https://nvlpubs.nist.gov/nistpubs/Legacy/hb/nbshandbook100.pdf" target="_blank" rel="noreferrer">Copper tables</a>.</p><p>Autosave is local to this browser. Export JSON to back up your project or move devices.</p></div>`;}
function modal(title,body,submit){const d=$('#modal');d.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${title}</h2>${btn('×','close-modal','close','aria-label="Close dialog"')}</div>${body}<div class="modal-actions">${btn('Cancel','close-modal','btn')}<button type="submit" class="btn primary">Continue</button></div></form>`;d.showModal();$('#modal-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);d.close();submit(data);};}
function transact(fn,redraw=true){const backup=structuredClone(project);try{fn();validateProject(project);save();if(redraw)render();return true;}catch(e){project=backup;render();toast(e.message);return false;}}
function confirmAction(title,detail,fn){modal(title,`<p>${esc(detail)}</p>`,()=>transact(fn));}
function allocatePowerTerminals(count){const used=new Set();for(const c of project.controllers)c.bankPsus.forEach((id,i)=>used.add(id+':'+c.bankPsuPorts[i]));for(const d of project.distros)used.add(d.psu+':'+d.psuPort);const result=[];for(let i=0;i<count;i++){let pair;for(const ps of project.psus){for(let port=1;port<=3;port++)if(!used.has(ps.id+':'+port)){pair=[ps.id,port];break;}if(pair)break;}if(!pair){const ps={id:uid(),name:'PSU '+String(project.psus.length+1).padStart(2,'0'),model:'unconfirmed',voltage:12,watts:320};project.psus.push(ps);pair=[ps.id,1];}used.add(pair.join(':'));result.push(pair);}return result;}
function addChain(controllerId,port){const c=project.controllers.find(c=>c.id===controllerId)||project.controllers.find(c=>project.chains.filter(ch=>ch.controller===c.id).length<BOARDS[c.model].ports);if(!c){toast('All ports are assigned. Add a controller.');return;}const n=port||Array.from({length:BOARDS[c.model].ports},(_,i)=>i+1).find(n=>!project.chains.some(ch=>ch.controller===c.id&&ch.port===n));if(!n||project.chains.some(ch=>ch.controller===c.id&&ch.port===n)){toast('That port is already assigned.');return;}transact(()=>{const ch={id:uid(),name:'New output · P'+n,controller:c.id,port:n,segments:[newSegment()]};project.chains.push(ch);selected=ch.id;si=0;page='workspace';});}
function usePreset(id){const p=project.presets.find(p=>p.id===id);active().segments.push(p?{...newSegment(),...p,id:uid(),name:undefined}:newSegment());si=active().segments.length-1;page='workspace';}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function csv(){const r=calculate(project),rows=[['Controller','Host','Port','Chain','Segment','Kind','Count','Channels_per_device','Start_channel','End_channel','Brightness_percent','Full_white_watts','Power_source','Vplus_isolated','Feed_metres','Feed_AWG','Fuse_A']];for(const ch of project.chains){let start=r.chains[ch.id].start;const c=project.controllers.find(c=>c.id===ch.controller);ch.segments.forEach((s,i)=>{const end=start+s.count*s.channels-1;rows.push([c.name,c.host,ch.port,ch.name,i+1,s.kind,s.count,s.channels,start,end,project.brightness,s.count*s.watts,sourceFor(ch,s,r),s.inject?'YES':'NO',s.inject?s.feedM:s.leadM,s.inject?s.feedAwg:s.leadAwg,s.inject?s.fuse:i===0?BOARDS[c.model].fuse:'upstream']);start=end+1;});}return rows.map(row=>row.map(v=>'"'+String(v).replace(/^([=+@-])/,"'$1").replace(/"/g,'""')+'"').join(',')).join('\r\n');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const [a,id,extra]=b.dataset.action.split(':');if(a==='close-modal'){$('#modal').close();return;}if(a==='page'){page=id;render();window.scrollTo({top:0});return;}if(a==='view'){view=id;render();return;}if(a==='select'){view='visual';selected=id;si=0;page='workspace';render();return;}if(a==='segment'){si=+id;render();return;}if(a==='export'||a==='csv'){const name=project.name.replace(/[^a-z0-9_-]/gi,'-')||'pixel-project';download(name+(a==='export'?'.json':'-channels.csv'),a==='export'?JSON.stringify(project,null,2):csv(),a==='export'?'application/json':'text/csv');toast(a==='export'?'Project downloaded.':'Planning CSV downloaded; configure FPP manually.');return;}if(a==='import'){$('#import-file').click();return;}if(a==='open-demo'){previousProject=project;previousLibrary=library;library=structuredClone(library);project=createDemoProject(library);demo=true;page='workspace';view='room';render();return;}if(a==='exit-demo'){if(!demo)return;project=previousProject||tailoredInitial();library=previousLibrary||library;previousProject=null;previousLibrary=null;demo=false;page='workspace';view='room';render();return;}if(a==='save-demo'){if(!demo)return;const copy=structuredClone(project);copy.name=copy.name.replace(/^Demo · /,'')+' copy';download('pixel-workbench-demo-copy.json',JSON.stringify(copy,null,2),'application/json');toast('Demo copy downloaded. Open the JSON to use it as a project.');return;}if(a==='blank-project'){modal('Blank this project?',`<p>This removes every controller, PSU, distro, output, preset, prop and room placement from the current project. Save a JSON backup first if you may need it again.</p><label>Type BLANK to confirm<input name="confirm" required autocomplete="off"></label>`,f=>{if(f.get('confirm')!=='BLANK'){toast('Project was kept. Type BLANK exactly to clear it.');return;}transact(()=>{project={version:1,name:'Untitled project',brightness:100,headroom:80,dropLimit:10,startChannel:1,psus:[],distros:[],controllers:[],chains:[],presets:[],aux:[],props:[],scene:{width:12,depth:8,snap:.1,placements:{}}};ensureInstallation(project);project.installation.infrastructureMigrated=true;selected='';si=0;page='workspace';view='room';});});return;}if(a==='new-box-main'){transact(()=>{const box=makeBox('Controller box '+(project.installation.boxes.length+1));project.installation.boxes.push(box);targetBoxId=box.id;openBox(box.id);page='boxes';});return;}if(a==='print'){window.print();return;}if(a==='add-chain'||a==='add-port'){addChain(id,+extra);return;}
 if(a==='add-controller'){modal('Add controller',`<label>Board<select name="model">${Object.entries(BOARDS).map(([id,b])=>`<option value="${id}">${b.name} · ${b.ports} outputs</option>`).join('')}</select></label><label>Name<input name="name" required maxlength="200" value="Baldrick ${project.controllers.length+1}"></label>`,f=>transact(()=>{const model=f.get('model'),n=BOARDS[model].banks,terminals=allocatePowerTerminals(n);const id=uid();project.controllers.push({id,model,name:f.get('name'),host:'',bankPsus:terminals.map(x=>x[0]),bankPsuPorts:terminals.map(x=>x[1]),bankLimits:Array(n).fill(0),bankM:Array(n).fill(.5),bankAwg:Array(n).fill(10),io:['','','']});addInfrastructure(project,library,'controller:'+id,targetBoxId);page='hardware';}));return;}
 if(a==='add-psu'){transact(()=>(()=>{const id=uid();project.psus.push({id,name:'PSU '+String(project.psus.length+1).padStart(2,'0'),model:'unconfirmed',voltage:12,watts:320});addInfrastructure(project,library,'psu:'+id,targetBoxId);})());return;}if(a==='add-distro'){transact(()=>{const [psu,psuPort]=allocatePowerTerminals(1)[0];const id=uid();project.distros.push({id,name:'Distro '+String(project.distros.length+1).padStart(2,'0'),psu,psuPort,outputs:6,amps:30,fuse:5});addInfrastructure(project,library,'distro:'+id,targetBoxId);});return;}
 if(a==='add-segment'){if(!active()){toast('Add an output first.');return;}modal('Add pixels or a flood',`<label>Preset<select name="preset">${project.presets.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}<option value="custom">Custom seed string</option></select></label>`,f=>transact(()=>usePreset(f.get('preset'))));return;}
 if(a==='new-preset'){transact(()=>project.presets.push({id:uid(),name:'My seed preset',kind:'seed',count:100,watts:.3,channels:3,spacing:.1,stringAwg:22}));return;}
 if(a==='use-preset'){if(!active()){toast('Add an output first.');return;}transact(()=>usePreset(id));return;}
 if(a==='save-preset'){if(!active()){toast('Select an output first.');return;}modal('Save pixel preset','<label>Preset name<input name="name" required maxlength="200" value="My pixel string"></label>',f=>transact(()=>{const {kind,count,watts,spacing,stringAwg,channels}=active().segments[si];project.presets.push({id:uid(),name:f.get('name'),kind,count,watts,spacing,stringAwg,channels});}));return;}
 if(a==='move'){const ch=active(),to=si+ +id;if(!ch||to<0||to>=ch.segments.length)return;transact(()=>{const [s]=ch.segments.splice(si,1);ch.segments.splice(to,0,s);si=to;});return;}
 if(a==='split'){const ch=active(),s=ch?.segments[si];if(!s||s.count<2){toast('Choose a segment with at least two devices.');return;}if(!project.distros.length){toast('Add a distro first.');return;}modal('Split & add a power feed',`<p>The second section gets a separate feed and an upstream V+ break.</p><label>Devices in first section<input type="number" name="count" min="1" max="${s.count-1}" step="1" value="${Math.ceil(s.count/2)}" required></label><label>Second section distro<select name="distro">${project.distros.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label>`,f=>transact(()=>{const n=+f.get('count'),d=project.distros.find(d=>d.id===f.get('distro')),next={...structuredClone(s),id:uid(),count:s.count-n,leadM:s.spacing,inject:true,psu:d.psu,distro:d.id,distroPort:undefined,feedM:2,feedAwg:18,fuse:d.fuse};s.count=n;ch.segments.splice(si+1,0,next);si++;}));return;}
 if(a==='add-aux'){modal('Add relay or input board','<label>Board<select name="model"><option value="switchy">BaldrickSwitchy · 4 relays</option><option value="input1">BaldrickInput1 · 1 input</option></select></label>',f=>transact(()=>{const model=f.get('model');const id=uid();project.aux.push({id,name:model==='switchy'?'Relay board':'Button board',model,psu:project.psus[0].id,watts:model==='switchy'?2.76:1,labels:Array(model==='switchy'?4:1).fill('')});addInfrastructure(project,library,'aux:'+id,targetBoxId);page='hardware';}));return;}
 if(a==='remove-chain'){const ch=active();if(ch)confirmAction('Remove output?',ch.name+' and all its segments will be removed.',()=>project.chains=project.chains.filter(c=>c.id!==ch.id));return;}
 if(a==='remove-segment'){const ch=active();if(!ch)return;if(ch.segments.length===1){toast('Use Remove output for the final segment.');return;}confirmAction('Remove segment?','The device order and channel ranges will be recalculated.',()=>{ch.segments.splice(si,1);si=0;});return;}
 if(a==='remove-psu'){if(project.psus.length===1||project.controllers.some(c=>c.bankPsus.includes(id))||project.distros.some(d=>d.psu===id)||project.aux.some(x=>x.psu===id)){toast('Reassign this PSU’s banks, distros and boards first.');return;}confirmAction('Remove PSU?','This unused supply will be removed.',()=>project.psus=project.psus.filter(x=>x.id!==id));return;}
 if(a==='remove-distro'){if(project.chains.some(c=>c.segments.some(s=>s.inject&&s.distro===id))){toast('Reassign this distro’s feeds first.');return;}transact(()=>project.distros=project.distros.filter(x=>x.id!==id));return;}
 if(a==='remove-controller'){if(project.controllers.length===1){toast('Keep at least one controller.');return;}confirmAction('Remove controller?','All its output chains will also be removed.',()=>{project.controllers=project.controllers.filter(c=>c.id!==id);project.chains=project.chains.filter(c=>c.controller!==id);});return;}
 if(a==='remove-preset'){transact(()=>project.presets=project.presets.filter(x=>x.id!==id));return;}if(a==='remove-aux'){confirmAction('Remove board?','Its labels and allowance will be removed.',()=>project.aux=project.aux.filter(x=>x.id!==id));return;}
});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="auto-inject"]');if(!button)return;const ch=active();if(!ch||!project.distros.length){toast('Select a chain and add a distro first.');return;}const s=ch.segments[si];modal('Suggest injection points',`<p>Calculate separately fed sections at ${project.brightness}% brightness and a maximum ${project.dropLimit}% voltage drop. New feeds use ${s.feedM} m / ${s.feedAwg} AWG. Adjust these feed assumptions in the inspector if needed.</p><label>Distro for new feeds<select name="distro">${project.distros.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label>`,f=>{try{const plan=recommendSections(project,ch.id,si,f.get('distro'));if(!plan.addedFeeds){toast('This segment already meets the selected voltage-drop and feed-fuse limits.');return;}modal('Review injection plan',`<p>${plan.addedFeeds} new feeds. Keep data continuous and isolate V+ at each new feed.</p><ol>${plan.sections.map(s=>`<li>Devices ${s.start}–${s.end}: ${s.count} devices · ${s.newFeed?'new distro feed':'existing feed'}</li>`).join('')}</ol><p>The plan checks PSU, distro and full-white limits separately after applying. It does not guarantee those limits will pass.</p>`,()=>transact(()=>{project=plan.project;si=0;}));}catch(err){toast(err.message);}});});
function edit(t,redraw=true){if(!t.dataset.bind)return;if(!t.checkValidity()){t.reportValidity();return;}const keys=t.dataset.bind.split('.'),last=keys.pop();transact(()=>{let obj=project;for(const k of keys)obj=obj[k];if(last==='powerMode'){obj.inject=t.value==='external';if(obj.inject){obj.distroPort=undefined;if(!project.distros.length)throw Error('Add a distro first.');const d=project.distros.find(d=>d.id===obj.distro)||project.distros[0];obj.distro=d.id;obj.psu=d.psu;obj.fuse=d.fuse;}return;}obj[last]=typeof obj[last]==='number'?+t.value:t.value;if(last==='distro'){obj.psu=project.distros.find(d=>d.id===obj.distro).psu;obj.distroPort=undefined;}if(keys[0]==='distros'&&last==='psu'){obj.psuPort=undefined;project.chains.forEach(c=>c.segments.filter(s=>s.distro===obj.id).forEach(s=>s.psu=obj.psu));}if(keys[0]==='psus'&&last==='model')Object.assign(obj,{voltage:12,watts:PSU_MODELS[obj.model].watts});if(keys[0]==='psus'&&last==='watts')obj.model='custom';if(last==='kind'){if(obj.kind==='flood'){obj.watts=10;obj.count=1;obj.spacing=0;}else{obj.watts=obj.kind==='seed'?.3:.6;obj.spacing=.1;}}if(keys[0]==='controllers'&&keys[2]==='bankPsus')project.controllers[+keys[1]].bankPsuPorts[+last]=undefined;if(last==='controller')obj.port=1;},redraw);}
document.addEventListener('change',e=>{if(e.target.id!=='import-file')edit(e.target);});
let timer;document.addEventListener('input',e=>{const t=e.target;if(!t.dataset.bind||t.tagName==='SELECT')return;clearTimeout(timer);const path=t.dataset.bind;if(!t.checkValidity())return;edit(t,false);timer=setTimeout(()=>{if(!t.isConnected||!t.checkValidity())return;const start=t.selectionStart,end=t.selectionEnd;render();const el=document.querySelector(`[data-bind="${CSS.escape(path)}"]`);el?.focus({preventScroll:true});if(el?.type==='text')el.setSelectionRange(start,end);},t.type==='range'?30:500);});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>6e6){toast('Project files must be smaller than 6 MB.');return;}try{const p=validateProject(JSON.parse(await f.text()));modal('Open project?',`<p>Replace the current project with “${esc(p.name)}”? Export a backup first if you need to retain the current version.</p>`,()=>{project=p;migrateInfrastructure(project,library);selected=p.chains[0]?.id;si=0;save();render();toast('Project opened.');});}catch(err){toast('Cannot open project: '+err.message);}});
installGraph({getProject:()=>project,transact,toast,split:(id,index)=>{selected=id;si=index;page='workspace';view='visual';render();document.querySelector('[data-action="split"]')?.click();}});
installRoom({linkRoom:(source,key)=>{
 const box=project.installation.boxes.find(b=>b.id===source.boxId);
 const part=box?.components.find(c=>c.id===source.componentId);
 const port=part?.snapshot.ports.find(v=>v.id===source.portId);
 if(!port)return;
 transact(()=>project.installation.connections.push({
  id:'link-'+uid(),boxId:box.id,
  ...(port.direction==='in'&&key.startsWith('field:')?{fromKey:key,fromPort:project.installation.fieldDevices.find(d=>'field:'+d.id===key)?.snapshot.ports[0]?.id,toKey:'box:'+box.id,toComponent:part.id,toPort:port.id}:{fromComponent:part.id,fromPort:port.id,fromKey:'box:'+box.id,toKey:key}),
  kind:port.type.includes('power')?'power':port.type.includes('pixel')?'data':'other',
  name:box.name+' / '+part.snapshot.name+' '+port.label+' to '+key,acknowledged:false
 }));
},showFieldLibrary:()=>{
 const defs=library.components.filter(d=>componentPlacement(d)!=='internal');
 const categories=[...new Set(defs.map(d=>d.category))].sort();
 modal('Add field device',`<label>Search<input type="search" data-catalog-search="field-modal" placeholder="Button, sensor, speaker"></label>
 <label>Category<select data-catalog-category="field-modal"><option value="">All categories</option>${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label>
 <div class="field-picker">${defs.map(d=>`<label data-catalog-item="field-modal" data-category="${esc(d.category)}" data-search="${esc([d.name,d.category,d.manufacturer,d.model,...(d.tags||[])].join(' ').toLowerCase())}"><input type="radio" name="definition" value="${esc(d.id)}" required> ${esc(d.icon)} ${esc(d.name)} <small>${esc(d.category)}</small></label>`).join('')}</div>`,
 f=>{const def=library.components.find(d=>d.id===f.get('definition'));if(def)transact(()=>{addFieldDevice(project,def);ensureScene(project);page='workspace';view='room';});});
},getLibrary:()=>library,getProject:()=>project,render,save,toast,transact,modal,confirmAction,newSegment,boardPorts:c=>BOARDS[c.model].ports,wiring:id=>{selected=id;si=0;view='visual';page='workspace';render();},showRoom:()=>{page='workspace';view='room';render();},showBoxes:id=>{openBox(id);page='boxes';render();}});
render();
if(document.modelContext?.registerTool){const life=new AbortController();const tools=[{name:'read_pixel_plan',description:'Read the local plan, calculated PSU loads and warnings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({project:structuredClone(project),calculation:calculate(project)})},{name:'set_planning_brightness',description:'Change local planning brightness and recalculate. Does not control real hardware.',inputSchema:{type:'object',properties:{percent:{type:'number',minimum:1,maximum:100}},required:['percent'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.percent!=='number'||!Number.isFinite(input.percent)||input.percent<1||input.percent>100)throw Error('percent must be 1 to 100');project.brightness=input.percent;save();render();return {brightness:project.brightness,watts:calculate(project).watts};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}




function libraryTransact(fn){const before=structuredClone(library);try{fn();if(!demo)localStorage.setItem('pixel-workbench-library-v1',JSON.stringify(library));render();return true;}catch(e){library=before;render();toast(e.message);return false;}}
document.addEventListener('input',e=>{if(e.target.matches('[data-catalog-search]'))filterCatalog(e.target.dataset.catalogSearch);});document.addEventListener('change',e=>{if(e.target.matches('[data-catalog-category]'))filterCatalog(e.target.dataset.catalogCategory);});function filterCatalog(scope){const query=(document.querySelector('[data-catalog-search="'+scope+'"]')?.value||'').toLowerCase().trim(),category=document.querySelector('[data-catalog-category="'+scope+'"]')?.value||'';document.querySelectorAll('[data-catalog-item="'+scope+'"]').forEach(el=>el.hidden=!!((query&&!el.dataset.search.includes(query))||(category&&el.dataset.category!==category)));}
